css.breakpoint_base:
@font-face{font-family:'Manrope';font-weight:400;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-400.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:500;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-500.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:600;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-600.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:700;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-700.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:800;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-800.ttf') format('truetype')}
.breakdance .evs-pg {
  --evs-font: 'Manrope', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --evs-bg: #F2F3F7; --evs-surface: #FFFFFF; --evs-night: #2C2F3F; --evs-text: #2C2F3F; --evs-body: #6B6F82; --evs-muted: #C9CCD6;
  --evs-sep: #E3E5EC; --evs-rowline: #EFEFF1; --evs-red: #FC2F55; --evs-signal: #E8445A; --evs-green: #1F8F5F;
  --evs-orange: #FFB340; --evs-blue: #409CFF; --evs-tint: rgba(232,68,90,.10);
  --evs-r-card: 20px; --evs-r: 12px; --evs-page: 16px; --evs-width: 1180px;
  font-family: var(--evs-font); color: var(--evs-text); -webkit-font-smoothing: antialiased;
}

.breakdance .evs-pg { background: var(--evs-bg); font-size: 14px; line-height: 20px; }
.breakdance .evs-pg.bde-section { padding: 0; }
.breakdance .evs-pg > .section-container { max-width: var(--evs-width); padding: 0 var(--evs-page); }
.breakdance .evs-pg h1, .breakdance .evs-pg h2, .breakdance .evs-pg h3 { font-family: var(--evs-font); margin: 0; color: var(--evs-text); text-wrap: balance; }
.breakdance .evs-pg .bde-div, .breakdance .evs-pg .bde-text, .breakdance .evs-pg .bde-shortcode, .breakdance .evs-pg .bde-button { min-width: 0; }
.breakdance .evs-pg :is(p, .breakdance a, .breakdance span, .breakdance div, .breakdance li, .breakdance button, .breakdance input, .breakdance select, .breakdance textarea, .breakdance b, .breakdance strong, .breakdance label) { font-family: var(--evs-font); }
/* Abschnittstitel wie SectionTitle/EvOpenSection: 20/800, über der Karte, ohne Strich */
.breakdance .evs-h2 { font-size: 20px !important; line-height: 1.25 !important; font-weight: 800 !important; letter-spacing: -.3px; }
.breakdance .evs-card { background: var(--evs-surface); border-radius: var(--evs-r-card); padding: 14px; box-sizing: border-box; width: 100%; }
.breakdance .evs-sechead { display: flex; flex-direction: row; align-items: baseline; justify-content: space-between; gap: 12px; width: 100%; }
.breakdance .evs-link .button-atom { all: unset; cursor: pointer; font-size: 13px; font-weight: 700; color: var(--evs-signal); white-space: nowrap; }
@media (min-width: 900px) {
  .breakdance .evs-pg { --evs-page: 32px; }
}

.breakdance .evp { position: relative; }
.breakdance .evp > .section-container { position: static; padding-bottom: 64px; }
/* roter Kopf mit Seitentitel (wie die Kopfleiste der App-Seiten) */
.breakdance .evp::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 84px; z-index: 0; border-radius: 0 0 28px 28px; background: var(--evs-red); }
.breakdance .evp-title { position: relative; z-index: 1; padding: 22px 0 0; font-size: 26px !important; line-height: 1.15 !important; font-weight: 800 !important; color: #fff !important; letter-spacing: -.4px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.breakdance .evp-content { position: relative; z-index: 1; width: 100%; margin-top: 40px; color: var(--evs-text); font-size: 14px; line-height: 20px; }
.breakdance .evp-content * { font-family: var(--evs-font) !important; }
.breakdance .evp-content .dashicons, .breakdance .evp-content .dashicons-before::before { font-family: dashicons !important; }

/* Tixomat-Variablen auf App-Werte (die Bausteine setzen sie an .tix-co, .tix-mt, .tix-sp-portal …) */
.breakdance .evp-content, .breakdance .evp-content * {
  --tix-primary: #2C2F3F; --tix-primary-rgb: 44,47,63; --tix-primary-hover: #3C4158; --tix-acc-primary: #E8445A !important;
  --tix-btn1-bg: #2C2F3F; --tix-btn1-color: #fff; --tix-btn1-hover-bg: #3C4158; --tix-btn1-hover-color: #fff; --tix-btn1-radius: 12px; --tix-btn1-border: none; --tix-btn1-font-size: .94rem;
  --tix-btn2-bg: transparent; --tix-btn2-color: #2C2F3F; --tix-btn2-hover-bg: #fff; --tix-btn2-hover-color: #2C2F3F; --tix-btn2-radius: 12px; --tix-btn2-border: 1px solid #C9CCD6; --tix-btn2-font-size: .94rem;
  --tix-buy-bg: #2C2F3F; --tix-buy-color: #fff; --tix-buy-hover: #3C4158; --tix-buy-hover-color: #fff; --tix-buy-radius: 12px;
  --tix-radius: 12px; --tix-input-radius: 12px; --tix-btn-radius: 50%; --tix-btn-size: 34px;
  --tix-border: #E3E5EC; --tix-input-border: #E3E5EC; --tix-input-focus: #2C2F3F; --tix-input-bg: #fff; --tix-cat-bg: #fff; --tix-co-bg: #fff; --tix-co-border: transparent;
  --tix-sale-color: #E8445A; --tix-success-color: #1F8F5F; --tix-text: #2C2F3F; --tix-font-body: 'Manrope', system-ui, sans-serif; --tix-font-heading: 'Manrope', system-ui, sans-serif;
  --tix-mt-bg: #F2F3F7; --tix-mt-card-bg: #fff; --tix-mt-border: transparent; --tix-mt-accent: #E8445A; --tix-mt-muted: rgba(44,47,63,.45); --tix-mt-ticket-bg: #fff;
}
.breakdance .evp-content a { color: var(--evs-signal); }
.breakdance .evp-content h2, .breakdance .evp-content h3 { color: var(--evs-text); font-weight: 800 !important; letter-spacing: -.3px; }
.breakdance .evp-content h2 { font-size: 20px !important; line-height: 1.25 !important; }
.breakdance .evp-content h3 { font-size: 16px !important; line-height: 1.3 !important; }

/* Eingaben + Knöpfe (App: Feld weiß Radius 12, Knopf nachtblau 50 hoch) */
.breakdance .evp-content :is(input[type=text], .breakdance input[type=email], .breakdance input[type=password], .breakdance input[type=tel], .breakdance input[type=number], .breakdance input[type=search], .breakdance select, .breakdance textarea) {
  border: 1px solid var(--evs-sep) !important; border-radius: 12px !important; background: #fff !important; box-shadow: none !important; min-height: 48px; font-size: 15px !important; color: var(--evs-text); }
.breakdance .evp-content textarea { min-height: 120px; }
.breakdance .evp-content :is(input, .breakdance select, .breakdance textarea):focus { border-color: var(--evs-night) !important; outline: none; }
.breakdance .evp-content :is(.tix-co-submit, .breakdance .tix-magic-btn, .breakdance .tix-sp-front-btn, .breakdance input[type=submit], .breakdance .button-primary, .breakdance #wp-submit) {
  background: var(--evs-night) !important; color: #fff !important; border: 0 !important; border-radius: 12px !important; min-height: 50px; font-weight: 600 !important; box-shadow: none !important; text-shadow: none !important; }
.breakdance .evp-content :is(.tix-co-btn-more, .breakdance .tix-sp-front-btn-ghost, .breakdance .tix-co-coupon button) {
  background: transparent !important; color: var(--evs-text) !important; border: 1px solid var(--evs-muted) !important; border-radius: 12px !important; font-weight: 600 !important; box-shadow: none !important; }
.breakdance .evp-content .tix-branding { opacity: .6; }

/* Kasse: Abschnitte als weiße Karten, Titel fett */
.breakdance .evp-content > * { max-width: 860px; margin-left: 0 !important; }
.breakdance .evp-content .tix-account-nav-item a { width: fit-content; }
.breakdance .evp-content .tix-co-section, .breakdance .evp-content .tix-co-legal, .breakdance .evp-content .tix-co-login-section { background: #fff !important; border: 0 !important; border-radius: 20px !important; padding: 16px 14px !important; box-shadow: none !important; margin-bottom: 14px; }
.breakdance .evp-content .tix-co-section:has(> .tix-co-summary-mini) { background: none !important; padding: 0 !important; margin: 0 !important; }
.breakdance .evp-content .tix-co-heading { border: 0 !important; padding: 0 !important; margin: 0 0 12px !important; font-size: 20px !important; font-weight: 800 !important; }
.breakdance .evp-content .tix-co-label { font-size: 12.5px !important; font-weight: 700 !important; color: var(--evs-body) !important; }
.breakdance .evp-content .tix-co-item { border: 0 !important; border-radius: 0 !important; padding: 12px 0 !important; background: none !important; }
.breakdance .evp-content .tix-co-item + .tix-co-item { border-top: 1px solid var(--evs-rowline) !important; }
.breakdance .evp-content .tix-co-item-name { font-weight: 800 !important; font-size: 14px !important; }
.breakdance .evp-content .tix-co-qty-btn { background: var(--evs-night) !important; color: #fff !important; border: 0 !important; border-radius: 50% !important; }
.breakdance .evp-content .tix-co-shipping-info { border-radius: 12px !important; border-color: var(--evs-sep) !important; background: var(--evs-bg) !important; }
.breakdance .evp-content .tix-co-summary-total, .breakdance .evp-content .tix-co-total { font-weight: 800 !important; }
.breakdance .evp-content .tix-co-check-custom { border-radius: 6px !important; border-color: var(--evs-muted) !important; }
.breakdance .evp-content .tix-co-link-btn { color: var(--evs-signal) !important; font-weight: 700; }

/* Konto: Reiter als Pillen, Zahlen-Kacheln und Schnellzugriff als Karten */
.breakdance .evp-content .tix-account-nav { border: 0 !important; margin-bottom: 18px; }
.breakdance .evp-content .tix-account-nav ul { display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; border: 0 !important; padding: 0 0 2px; margin: 0; }
.breakdance .evp-content .tix-account-nav-item { list-style: none; flex: none; border: 0 !important; margin: 0 !important; }
.breakdance .evp-content .tix-account-nav-item a { display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 14px; border-radius: 999px; background: #fff; color: var(--evs-text) !important;
  font-size: 13px; font-weight: 600; border: 0 !important; text-decoration: none; white-space: nowrap; }
.breakdance .evp-content .tix-account-nav-item a .dashicons { font-size: 16px; width: 16px; height: 16px; color: var(--evs-signal); }
.breakdance .evp-content .tix-account-nav-item.is-active a { background: var(--evs-night); color: #fff !important; }
.breakdance .evp-content .tix-account-nav-item.is-active a .dashicons { color: #fff; }
.breakdance .evp-content .tix-account-dashboard > h2 { font-size: 23px !important; }
.breakdance .evp-content .tix-account-subtitle { color: var(--evs-body); font-size: 13.5px; }
.breakdance .evp-content .tix-account-stat { background: #fff !important; border: 0 !important; border-radius: 20px !important; box-shadow: none !important; }
.breakdance .evp-content .tix-account-stat-value { color: var(--evs-text) !important; font-weight: 800 !important; }
.breakdance .evp-content .tix-account-stat-label { color: var(--evs-body) !important; font-size: 12.5px !important; }
.breakdance .evp-content .tix-account-stat .dashicons, .breakdance .evp-content .tix-account-link .dashicons { color: var(--evs-signal) !important; }
.breakdance .evp-content .tix-account-links-grid { gap: 0 !important; background: #fff; border-radius: 20px; padding: 2px 14px; }
.breakdance .evp-content .tix-account-link { background: none !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; padding: 14px 0 !important; color: var(--evs-text) !important; font-weight: 600; }
.breakdance .evp-content .tix-account-link + .tix-account-link { border-top: 1px solid var(--evs-rowline) !important; }
.breakdance .evp-content .tix-account-login > h2, .breakdance .evp-content .tix-account-login-icon { display: none !important; }
.breakdance .evp-content .tix-account-login { background: #fff; border-radius: 20px; padding: 16px 14px; }
.breakdance .evp-content .tix-magic-block { background: #fff !important; border: 0 !important; border-radius: 20px !important; box-shadow: none !important; }
.breakdance .evp-content .tix-magic-title { font-size: 16px !important; }

/* Meine Tickets / Bestellungen (tix-mt) */
.breakdance .evp-content .tix-mt { background: transparent !important; }
.breakdance .evp-content :is(.tix-mt-card, .breakdance .tix-mt-ticket, .breakdance .tix-mt-order) { border: 0 !important; border-radius: 20px !important; box-shadow: none !important; }

/* Support */
.breakdance .evp-content #tix-sp-front-auth > h2 { display: none; }
.breakdance .evp-content .tix-sp-front-section { background: #fff !important; border: 0 !important; border-radius: 20px !important; padding: 16px 14px !important; box-shadow: none !important; }

@media (min-width: 900px) {
  .breakdance .evp::before { height: 120px; }
  .breakdance .evp-title { padding-top: 36px; font-size: 34px !important; }
  .breakdance .evp-content { margin-top: 56px; }
}
